      {/* Edit Spec Modal — xem được mọi lúc, chỉ sửa được khi master CHƯA approved */}
      <Modal
        open={!!editRow}
        title={`${editRow?.schema_status === 'approved' ? 'Xem Spec' : 'Edit Spec'}: ${editRow?.master_schema}.${editRow?.master_name}`}
