            message.error('Spec phải là JSON hợp lệ');
            return;
          }
          if (!parsedSpec || typeof parsedSpec !== 'object' || Array.isArray(parsedSpec) || typeof parsedSpec.pk !== 'string' || !parsedSpec.pk.trim()) {
            message.error('Spec (JSON) bắt buộc phải có trường "pk" không rỗng (ví dụ: {"pk":"_id"})');
